from __future__ import annotations

import asyncio
import datetime as dt
import sys
from pathlib import Path

import polars as pl
import pytest
from pydantic import BaseModel
from pydantic_ai.messages import ModelMessage, ModelResponse, ToolCallPart, UserPromptPart
from pydantic_ai.models.function import AgentInfo, FunctionModel

# the app has no package install: import it from its folder
APP_DIR = Path(__file__).resolve().parents[3] / "experimental" / "reflex-kernel"
sys.path.insert(0, str(APP_DIR))

from reflex_kernel import assign  # noqa: E402
from reflex_kernel.commands import SLASH  # noqa: E402
from reflex_kernel.session import Session  # noqa: E402

RECORD = "\n".join(
    [
        "class PlayerSummary(BaseModel, frozen=True):",
        "    tag: str",
        "    wins: int",
        "    chars: list[str]",
        "",
        "helper = 3",
        'leo = PlayerSummary(tag="MkLeo", wins=helper, chars=["Joker", "Byleth"])',
    ]
)


@pytest.fixture
def session() -> Session:
    made = Session()
    made.namespace["q1"] = pl.DataFrame({"player": ["a", "b"], "wins": [1, 2]})
    return made


class Point(BaseModel):
    x: int
    tags: list[str] = []
    when: dt.date | None = None


class Nested(BaseModel):
    inner: dict[str, int]


# -- "/assign name = text" ---------------------------------------------------------------


def test_the_name_is_the_users_when_given() -> None:
    assert assign.split("top5 = the five best players") == ("top5", "the five best players")
    assert assign.split("the five best players") == ("", "the five best players")
    # a comparison in the text is not a name
    assert assign.split("who == best") == ("", "who == best")
    assert assign.split("") == ("", "")


def test_the_command_takes_text() -> None:
    assert SLASH["assign"].takes
    assert SLASH["assign"].slash_event == ("assign_ask",)


# -- which code and values are allowed ---------------------------------------------------


def test_the_code_must_end_with_one_plain_assignment() -> None:
    assert assign.target("a = 1\nbest = a + 1") == "best"
    assert assign.target("best: int = 2") == "best"
    assert assign.target("print(1)") == ""
    assert assign.target("a, b = 1, 2") == ""
    assert assign.target("not python (") == ""
    assert "valid Python" in assign.code_problem("not python (")
    assert "assignment" in assign.code_problem("print(1)")
    assert assign.code_problem("best = 1") == ""


@pytest.mark.parametrize(
    "value",
    [
        "Steve",
        3,
        2.5,
        True,
        dt.date(2018, 12, 7),
        dt.datetime(2018, 12, 7, 10, 0),  # a plain value for the type check
        dt.timedelta(days=2),
        ["Steve", "Sonic"],
        [1, 2.5],
        [],
        pl.DataFrame({"a": [1]}),
        Point(x=1, tags=["a"], when=dt.date(2020, 1, 1)),
        Point(x=1),
    ],
    ids=lambda value: type(value).__name__,
)
def test_structured_values_are_allowed(value: object) -> None:
    assert assign.value_problem(value) == ""


@pytest.mark.parametrize(
    ("value", "why"),
    [
        ({"a": 1}, "dict is unstructured"),
        (None, "None"),
        ([{"a": 1}], "DataFrame"),
        ([Point(x=1)], "DataFrame"),
        ([1, "a"], "mixes"),
        ([True, 2], "mixes"),
        ((1, 2), "tuple"),
        ({1, 2}, "set"),
        (pl.Series("a", [1]), "Series"),
        (Nested(inner={"a": 1}), "field inner"),
    ],
    ids=lambda value: type(value).__name__,
)
def test_unstructured_values_are_refused(value: object, why: str) -> None:
    assert why in assign.value_problem(value)


# -- running a proposal ------------------------------------------------------------------


def test_run_binds_a_computed_value(session: Session) -> None:
    ran = assign.run(session, 'best = q1.sort("wins")["player"][-1]')
    assert (ran.name, ran.error, ran.replaced) == ("best", "", False)
    assert session.namespace["best"] == "b"
    assert session.sources["best"] == assign.SOURCE
    assert assign.run(session, "best = 'c'").replaced


def test_run_binds_a_literal_from_knowledge(session: Session) -> None:
    assert assign.run(session, "release = datetime.date(2018, 12, 7)").name == "release"
    assert session.namespace["release"] == dt.date(2018, 12, 7)
    # the helpers given to the code are not left in the session
    assert "datetime" not in session.namespace
    assert "BaseModel" not in session.namespace


def test_run_keeps_a_records_class_but_not_helper_names(session: Session) -> None:
    ran = assign.run(session, RECORD)
    assert (ran.name, ran.classes) == ("leo", ["PlayerSummary"])
    assert session.namespace["leo"].chars == ["Joker", "Byleth"]
    assert isinstance(session.namespace["leo"], session.namespace["PlayerSummary"])
    assert "helper" not in session.namespace


@pytest.mark.parametrize(
    ("code", "why"),
    [
        ('d = {"a": 1}', "dict is unstructured"),
        ("y = 1 / 0", "ZeroDivisionError"),
        ("print(1)", "assignment"),
        ("pl = 3", "predefined"),
        ("_hidden = 3", "hidden"),
        ("helper = 1\nrows = [{'a': helper}]", "DataFrame"),
    ],
)
def test_run_binds_nothing_when_it_fails_or_the_value_is_refused(session: Session, code: str, why: str) -> None:
    before = dict(session.namespace)
    ran = assign.run(session, code)
    assert ran.name == ""
    assert why in ran.error
    assert session.namespace == before


def test_a_failing_run_has_a_traceback_and_a_refusal_has_none(session: Session) -> None:
    assert assign.run(session, "y = 1 / 0").trace
    assert not assign.run(session, 'd = {"a": 1}').trace


# -- the proposal --------------------------------------------------------------------------


def answering(answers: list[dict[str, str]], seen: list[str]) -> FunctionModel:
    """A stand-in model that proposes each of `answers` in turn (the last one again after)."""
    asked = 0

    def respond(messages: list[ModelMessage], info: AgentInfo) -> ModelResponse:
        nonlocal asked
        seen.extend(str(part.content) for part in messages[-1].parts if isinstance(part, UserPromptPart))
        answer = answers[min(asked, len(answers) - 1)]
        asked += 1
        return ModelResponse(parts=[ToolCallPart(info.output_tools[0].name, answer)])

    return FunctionModel(respond)


def propose(session: Session, text: str, answers: list[dict[str, str]], seen: list[str]) -> assign.Proposal:
    with assign.assign_agent.override(model=answering(answers, seen)):
        return asyncio.run(assign.propose(session, "no-such-token", text))


def test_a_proposal_is_code_to_review_and_nothing_is_run(session: Session) -> None:
    seen: list[str] = []
    code = 'best = q1.sort("wins")["player"][-1]'
    answer = propose(
        session, "the player with most wins in @q1", [{"name": "best", "code": code, "basis": "computed"}], seen
    )
    assert (answer.name, answer.code, answer.basis, answer.error) == ("best", code, assign.COMPUTED, "")
    assert "best" not in session.namespace
    # the model was told what to make, to pick the name, and what the mentioned variable holds
    assert "should hold: the player with most wins in @q1" in seen[0]
    assert "Pick its name." in seen[0]
    assert session.namespace["q1"].write_csv() in seen[0]


def test_the_users_name_is_kept_and_a_proposal_for_another_goes_back(session: Session) -> None:
    seen: list[str] = []
    answers = [
        {"name": "other", "code": "other = 1", "basis": "knowledge"},
        {"name": "top", "code": "top = 1", "basis": "knowledge"},
    ]
    answer = propose(session, "top = the number one", answers, seen)
    assert (answer.name, answer.basis) == ("top", assign.KNOWLEDGE)
    assert "Name it top." in seen[0]


def test_what_cant_be_asked_never_reaches_the_model(session: Session) -> None:
    seen: list[str] = []
    assert "Say what" in propose(session, "  ", [], seen).error
    assert "predefined" in propose(session, "pl = polars again", [], seen).error
    assert not seen
